def solve_near_numbers():
    bases = [1, 2, 3, 4]
    exponents = [1, 2, 3]
    solutions = []

    # Iterate over all possible combinations of (n_B, a, n_T, b, n_S, c)
    for nB in bases:
        for a in exponents:
            B = nB**a + 1

            for nT in bases:
                for b in exponents:
                    T = nT**b + 1

                    for nS in bases:
                        for c in exponents:
                            S = nS**c + 1

                            if B + T == S:
                                # Found a solution. Store the triple (B, T, S)
                                solutions.append((B, T, S))

    return solutions

solutions = solve_near_numbers()
print(f"Found {len(solutions)} solutions.")
for sol in solutions:
    print(sol)

