# Let's check the full constraints for reporting.
# (B, T, S) are the required output elements.
if solutions:
    print("\nList of unique triples (B, T, S):")
    unique_solutions = sorted(list(set(solutions)))
    for sol in unique_solutions:
        print(sol)
else:
    print("No solutions found under the given constraints.")
